(function(){
 'use strict';const M=LearningModel,{n,download}=PlatformUI,article=document.getElementById('article');if(!article)return;
 let storage;try{storage=localStorage;}catch{}const store=new M.Store(storage);let book=null,section=null,selection=null,returnFocus=null,unsaved=false;
 const make=n('button','Карточка','quiet outlined');make.type='button';make.id='makeFlashcard';make.disabled=true;make.title='Создать карточку из выделенного текста';document.querySelector('.reader-tools')?.append(make);
 const fromNote=n('button','В карточку','quiet outlined');fromNote.type='button';fromNote.id='notesFlashcard';document.querySelector('#notesDialog .dialog-actions')?.append(fromNote);
 const storageNotice=n('p',undefined,'platform-error');storageNotice.hidden=true;storageNotice.setAttribute('role','alert');document.querySelector('.reader-tools')?.after(storageNotice);const exportMemory=()=>{download('psycholibrary-practice-backup.json',{format:'psycholibrary-practice-backup',schemaVersion:1,state:store.state});unsaved=false;};window.addEventListener('beforeunload',e=>{if(unsaved){e.preventDefault();e.returnValue='';}});
 const dialog=n('dialog',undefined,'learning-dialog');dialog.id='flashcardDialog';dialog.setAttribute('aria-labelledby','flashcardTitle');
 const head=n('div',undefined,'dialog-head'),title=n('h2','Карточка для повторения');title.id='flashcardTitle';const close=n('button','✕','quiet');close.type='button';close.setAttribute('aria-label','Закрыть создание карточки');close.onclick=()=>dialog.close();head.append(title,close);
 const form=n('form',undefined,'learning-form'),ql=n('label','Вопрос'),question=n('input');question.type='text';question.required=true;question.maxLength=10000;question.id='flashcardQuestion';ql.append(question);const al=n('label','Ответ'),answer=n('textarea');answer.required=true;answer.maxLength=10000;answer.id='flashcardAnswer';al.append(answer);
 const context=n('p',undefined,'learning-small'),message=n('p',undefined,'platform-status');message.id='flashcardStatus';message.setAttribute('role','status');const submit=n('button','Сохранить карточку','primary');submit.type='submit';form.append(ql,al,context,submit);dialog.append(head,n('p','Сначала сформулируйте вопрос. Выбранный текст можно отредактировать; ссылка на исходный раздел сохранится.','learning-small'),form,message);document.body.append(dialog);
 function capture(){const s=getSelection();if(!s||!String(s).trim()||!article.contains(s.anchorNode)||!article.contains(s.focusNode)){selection=null;return;}const element=s.anchorNode.nodeType===1?s.anchorNode:s.anchorNode.parentElement;selection={text:String(s),block:Number(element.closest('[data-block]')?.dataset.block||0),sectionId:section?.id};}
 document.addEventListener('selectionchange',capture);make.onpointerdown=capture;
 let source=null;
 function open(text,block,trigger){if(!book||!section)return;returnFocus=trigger;source={book:book.id.startsWith('fish')?'fish':'oxford',sectionId:section.id,block:Number.isInteger(block)?block:0,title:section.title};question.value='';answer.value=text.slice(0,10000);context.textContent=(source.book==='fish'?'Фиш':'Oxford')+' · '+source.title;message.textContent=(text.length>10000?'Вставлены первые 10 000 символов. ':'')+(store.notice||'');dialog.showModal();question.focus();}
 make.onclick=()=>{const selected=selection?.sectionId===section?.id?selection:null;open(selected?.text||'',selected?.block,make);};
 fromNote.onclick=()=>{const notes=document.getElementById('personalNotes'),start=notes.selectionStart,end=notes.selectionEnd,text=end>start?notes.value.slice(start,end):notes.value;document.getElementById('notesDialog').close();open(text,0,document.getElementById('notesButton'));};
 form.onsubmit=e=>{e.preventDefault();if(!question.value.trim()||!answer.value.trim())return;try{store.update(M.newId('card'),{kind:'card',question:question.value.trim(),answer:answer.value.trim(),source,stage:0,dueAt:Date.now(),reviews:0});message.replaceChildren(n('span',store.writable?'Карточка сохранена. ':'Карточка доступна в этой вкладке; сохранение недоступно. '));const a=n('a','Открыть карточки →');a.href='workshop.html#cards';if(store.writable)message.append(a);if(!store.writable){unsaved=true;storageNotice.replaceChildren(n('span','Карточки пока только в этой вкладке. Скачайте копию перед переходом на другую страницу. '));const copy=n('button','Скачать карточки и практику','quiet outlined');copy.type='button';copy.onclick=exportMemory;storageNotice.append(copy);storageNotice.hidden=false;const exportButton=n('button','Скачать копию практики','quiet outlined');exportButton.type='button';exportButton.onclick=exportMemory;message.append(exportButton);}submit.disabled=true;}catch(err){message.textContent=err.message;}};
 dialog.onclose=()=>{submit.disabled=false;returnFocus?.focus({preventScroll:true});};
 window.ReaderCards={configure(b,s){book=b;section=s;selection=null;make.disabled=!s?.blocks?.length;fromNote.disabled=!s;},clear(){book=null;section=null;selection=null;make.disabled=true;fromNote.disabled=true;}};
})();
